export const L = {"a1":{"t0":3.23,"t1":6.354,"text":"Một vòng lộn của Tôn Ngộ Không đi được mười vạn tám ngàn dặm."},"a2":{"t0":7.014,"t1":8.724,"text":"Tây Thiên cũng cách đúng chừng ấy."},"a3":{"t0":9.384,"t1":11.92,"text":"Vậy mà thầy trò Đường Tăng đi mất mười bốn năm."},"a4":{"t0":12.58,"t1":17.196,"text":"Không phải vì không có cách. Mà vì chuyến đi này không phải để tới nơi."},"a5":{"t0":17.856,"t1":20.564,"text":"Nó là một vở kịch, đã được dàn dựng từ trước."},"a6":{"t0":23.394,"t1":28.193,"text":"Trong mười bốn năm ấy, có tám mươi mốt tai nạn được ghi lại, đánh số, và đếm lại."},"a7":{"t0":28.853,"t1":33.448,"text":"Và câu hỏi của phim này rất đơn giản: nếu đó là một vở kịch, ai là đạo diễn?"},"b1":{"t0":41.848,"t1":45.294,"text":"Chương một. Vở kịch được viết trước khi có diễn viên."},"b2":{"t0":45.954,"t1":53.028,"text":"Hồi thứ tám. Phật Tổ Như Lai nói: cõi Tây phương có ba tạng kinh; Đông Thổ cần, phải có người tới lấy."},"b3":{"t0":53.688,"t1":56.036,"text":"Quán Thế Âm nhận lệnh đi tìm người thỉnh kinh."},"b4":{"t0":56.696,"t1":59.254,"text":"Dọc đường, bà gặp ba kẻ đang chịu tội."},"b5":{"t0":59.914,"t1":66.462,"text":"Lời mời của bà đọc lên như một hợp đồng: theo ta hộ tống người thỉnh kinh; xong việc, tội được xóa, chức cũ được trả."},"b6":{"t0":67.122,"t1":71.747,"text":"Sa Tăng nhận. Trư Bát Giới nhận. Tôn Ngộ Không nhận."},"b7":{"t0":72.407,"t1":78.326,"text":"Bốn người, một con ngựa, một con đường. Nhưng hợp đồng đã ký trước khi con đường bắt đầu."},"b8":{"t0":78.986,"t1":82.379,"text":"Và người ta chỉ ký hợp đồng khi đã biết vở diễn kết thúc thế nào."},"b9":{"t0":83.039,"t1":89.589,"text":"Người thỉnh kinh không tự nguyện. Ông được chọn trong một đàn chay do vua tổ chức, rồi được trao một bộ cà sa."},"b10":{"t0":90.249,"t1":96.985,"text":"Ba người kia cũng không tự nguyện. Họ đang chịu hình phạt. Đây là cơ hội duy nhất để được tha."},"b11":{"t0":97.645,"t1":105.297,"text":"Quán Thế Âm đi từ tây sang đông, gặp từng người một. Bà không hỏi họ muốn gì. Bà nói họ sẽ được gì."},"c1":{"t0":110.697,"t1":113.494,"text":"Chương hai. Cuốn sổ của đạo diễn."},"c2":{"t0":114.154,"t1":119.561,"text":"Quán Thế Âm giữ một cuốn sổ gọi là nạn bạ. Mỗi nạn một dòng, đánh số."},"c3":{"t0":120.221,"t1":124.381,"text":"Khi thầy trò về tới Linh Sơn, bà mở sổ, đếm: tám mươi nạn."},"c4":{"t0":125.041,"t1":130.182,"text":"Rồi bà nói một câu mà không vở kịch nào dám nói to: còn thiếu một nạn, chưa đủ số."},"c5":{"t0":133.412,"t1":136.148,"text":"Bà sai người đuổi theo: làm thêm một nạn nữa."},"c6":{"t0":136.808,"t1":141.407,"text":"Không phải tai nạn. Không phải số phận. Một chỉ thị."},"c7":{"t0":142.067,"t1":148.408,"text":"Và nạn thứ nhất trong sổ không phải lúc lên đường. Là lúc bị đày xuống trần, trước khi Đường Tăng được sinh ra."},"c8":{"t0":149.068,"t1":154.44,"text":"Cuốn sổ bắt đầu trước nhân vật. Nó không ghi lại chuyến đi; nó lên lịch cho chuyến đi."},"c9":{"t0":156.27,"t1":165.811,"text":"Tám mươi mốt là con số của Phật giáo: chín lần chín, trở về chân như. Nó không phải số tai nạn xảy ra. Nó là số tai nạn phải xảy ra."},"c10":{"t0":166.471,"t1":171.171,"text":"Và người giữ sổ không phải người đi đường. Là người ngồi trên tòa sen."},"c11":{"t0":171.831,"t1":178.817,"text":"Nạn bạ không phải nhật ký. Nhật ký ghi cái đã xảy ra. Nạn bạ ghi cái phải xảy ra."},"c12":{"t0":179.477,"t1":181.657,"text":"Và người đếm là người đã viết kịch bản."},"d1":{"t0":187.257,"t1":190.418,"text":"Chương ba. Yêu quái nào cũng có người quen."},"d2":{"t0":191.078,"t1":195.497,"text":"Ở núi Bình Đỉnh, hai con yêu quái bị bắt. Lão Tử xuống đòi."},"d3":{"t0":196.157,"t1":199.986,"text":"Ông nói: đó là hai đứa trẻ giữ lò vàng, lò bạc của ta."},"d4":{"t0":200.646,"t1":211.573,"text":"Rồi ông nói thêm một câu, và cả vở kịch đứng hình. Chính Bồ Tát Quán Thế Âm đã hỏi mượn ta ba lần, đưa chúng xuống đây, hóa thành yêu quái, để thử xem thầy trò có thật lòng đi Tây Thiên không."},"d5":{"t0":215.603,"t1":220.363,"text":"Không phải yêu quái. Là diễn viên quần chúng, do chính người bảo trợ tuyển."},"d6":{"t0":221.023,"t1":229.852,"text":"Những lần khác cũng vậy. Sư tử của Văn Thù. Cá vàng trong ao sen của Quán Âm. Con sư tử lông vàng bà cưỡi."},"d7":{"t0":230.512,"t1":236.312,"text":"Con nào cũng có chủ. Và chủ luôn tới đúng lúc gậy sắp giáng xuống: khoan, con ta."},"d8":{"t0":236.972,"t1":247.081,"text":"Ở núi Sư Đà, ba con yêu quái lớn nhất: sư tử của Văn Thù, voi của Phổ Hiền, và đại bàng, anh em cùng mẹ với chim khổng tước, kẻ mà Phật Tổ từng gọi là cậu của mình."},"d9":{"t0":247.741,"t1":254.866,"text":"Đại bàng từ chối lên trời. Nó nói: trên đó ăn chay, nghèo lắm; ở đây ta ăn thịt người, sướng hơn."},"d10":{"t0":255.526,"t1":258.774,"text":"Còn ba con tê giác ở núi Thanh Long thì không có ai tới đòi."},"d11":{"t0":259.434,"t1":265.106,"text":"Chúng bị giết. Sừng bị cưa. Một chiếc sừng được gửi lên Linh Sơn làm quà."},"d12":{"t0":265.766,"t1":272.107,"text":"Câu yêu quái có ô dù thì được đón về, không có thì bị đánh chết, là câu của Internet, không có trong truyện."},"d13":{"t0":272.767,"t1":276.298,"text":"Nhưng ba con tê giác thì có thật. Và chúng chết thật."},"d14":{"t0":278.128,"t1":286.306,"text":"Không phải vì truyện tàn nhẫn. Vì truyện rất nhất quán: cái gì thuộc về ai thì trả về người đó; cái gì không thuộc về ai thì bị xóa."},"d15":{"t0":286.966,"t1":289.977,"text":"Và trong một vở diễn, ai cũng phải thuộc về một người."},"d16":{"t0":290.637,"t1":299.392,"text":"Đại bàng đòi ăn thịt cả một nước. Phật Tổ hứa: ai làm việc thiện, ta cho ngươi ăn trước. Một thỏa thuận, không phải một hình phạt."},"e1":{"t0":304.992,"t1":307.973,"text":"Chương bốn. Kinh sách là một món hàng."},"e2":{"t0":308.633,"t1":314.8,"text":"Đường Tăng tới Linh Sơn. Hai đệ tử của Phật dẫn vào kho, rồi hỏi: có nhân sự không?"},"e3":{"t0":315.46,"t1":320.086,"text":"Nhân sự nghĩa là quà. Không có quà, họ đưa kinh không chữ."},"e4":{"t0":320.746,"t1":322.686,"text":"Năm ngàn bốn mươi tám cuộn giấy trắng."},"e5":{"t0":323.346,"t1":329.206,"text":"Phật Tổ biết. Ngài cười, và phán: kinh không thể truyền không công, cũng không thể lấy không."},"e6":{"t0":329.866,"t1":335.491,"text":"Ngài kể chuyện lần trước bán kinh cho một nhà giàu, lấy ba đấu ba thăng vàng, mà còn chê là bán rẻ."},"e7":{"t0":336.151,"t1":341.35,"text":"Đường Tăng không có gì. Chỉ có chiếc bình bát bằng vàng, do chính vua Đường ban."},"e8":{"t0":342.01,"t1":350.02,"text":"Ông đưa. Vị đệ tử nhận, mỉm cười. Các vị khác trêu: không biết xấu hổ à, đòi quà của người ta."},"e9":{"t0":350.68,"t1":352.544,"text":"Nhưng tay thì vẫn giữ chặt chiếc bình."},"e10":{"t0":354.374,"t1":358.818,"text":"Đổi lại, họ đưa kinh có chữ: năm ngàn bốn mươi tám cuộn, đúng một tạng."},"e11":{"t0":359.478,"t1":362.044,"text":"Và chuyến đi kéo dài năm ngàn bốn mươi tám ngày."},"e12":{"t0":362.704,"t1":367.222,"text":"Cùng một con số. Không phải ngẫu nhiên. Là định mức."},"e13":{"t0":367.882,"t1":375.582,"text":"Người trả tiền thật không phải nhà sư. Là vua Đường, người dựng đàn chay bốn mươi chín ngày để yên lòng các oan hồn trong giấc mơ của mình."},"e14":{"t0":376.242,"t1":380.165,"text":"Ông hỏi: bao giờ về? Nhà sư đáp: ba năm."},"e15":{"t0":380.825,"t1":382.444,"text":"Mười bốn năm sau mới về."},"e16":{"t0":384.274,"t1":392.286,"text":"Kinh không chữ không phải trò lừa. Nó là món hàng thử: nếu người mua không biết mình mua gì, thì thứ họ nhận được đúng là không có gì."},"e17":{"t0":392.946,"t1":397.803,"text":"Nhưng khi đã trả giá, họ nhận được chữ. Và chữ nào cũng có giá."},"e18":{"t0":398.463,"t1":402.601,"text":"Nhà văn Minh viết về thiên đình, nhưng cái kho đọc lên thấy giống hệt một công đường."},"e19":{"t0":403.261,"t1":407.584,"text":"Món hàng ấy không phải giấy. Là quyền nói rằng trời đã chứng giám."},"f1":{"t0":413.984,"t1":417.294,"text":"Chương năm. Thứ duy nhất không có trong kịch bản."},"f2":{"t0":417.954,"t1":425.707,"text":"Trên đường về, họ qua sông Thông Thiên. Con rùa già chở họ, rồi hỏi: tôi nhờ hỏi Phật, tôi còn sống được bao lâu?"},"f3":{"t0":426.367,"t1":427.296,"text":"Đường Tăng quên."},"f4":{"t0":428.227,"t1":430.191,"text":"Rùa lặn. Kinh ướt."},"f5":{"t0":430.851,"t1":435.209,"text":"Họ phơi kinh trên đá. Một cuộn bị dính, rách mất phần cuối."},"f6":{"t0":435.869,"t1":448.595,"text":"Đường Tăng hối hận. Ngộ Không cười: không phải lỗi ở đây. Trời đất còn không trọn vẹn; kinh này vốn đã trọn, nay bị rách, ấy là ứng với lẽ không trọn vẹn. Sức người nào làm được?"},"f7":{"t0":452.225,"t1":456.927,"text":"Đó là câu duy nhất trong cả vở kịch thừa nhận: có một chỗ, kịch bản không với tới."},"f8":{"t0":457.587,"t1":461.908,"text":"Và chỗ đó không phải tai nạn. Là một lỗ hổng được giữ lại."},"f9":{"t0":463.738,"t1":471.035,"text":"Nhà phê bình Hồ Thích nói: đừng tìm ẩn ý. Truyện này là một trò đùa, một thứ châm biếm lạnh, và giá trị của nó nằm ở đó."},"f10":{"t0":471.695,"t1":476.195,"text":"Ông đúng. Nhưng một trò đùa về một vở diễn thì vẫn là một vở diễn."},"f11":{"t0":476.855,"t1":481.996,"text":"Nạn thứ tám mươi mốt không do ai lên kế hoạch. Nó do một con rùa già quyết định."},"f12":{"t0":482.656,"t1":484.985,"text":"Và đó là nạn duy nhất làm hỏng món hàng."},"f13":{"t0":485.645,"t1":490.991,"text":"Đó là lý do câu chuyện phải để nó rách. Một món hàng hoàn hảo thì không cần người đọc."},"g1":{"t0":496.791,"t1":498.874,"text":"Chương sáu. Khán giả."},"g2":{"t0":499.534,"t1":502.875,"text":"Ở bến Lăng Vân, thầy trò qua sông trên con thuyền không đáy."},"g3":{"t0":503.535,"t1":508.838,"text":"Một cái xác trôi ngang. Cả bốn người cùng chỉ tay. Chính là ông."},"g4":{"t0":509.498,"t1":513.754,"text":"Người thỉnh kinh cũ đã chết giữa sông. Người qua bờ là người khác."},"g5":{"t0":515.984,"t1":521.813,"text":"Lên tới Linh Sơn, họ được phong. Đường Tăng thành Phật. Ngộ Không thành Phật."},"g6":{"t0":522.473,"t1":524.887,"text":"Ngộ Không sờ đầu: cái vòng đã biến mất."},"g7":{"t0":525.547,"t1":528.749,"text":"Ông xin đập vỡ nó, để không ai bị trò đó chơi nữa."},"g8":{"t0":529.409,"t1":532.064,"text":"Và đây là câu trả lời cho câu hỏi ở đầu phim."},"g9":{"t0":533.694,"t1":543.532,"text":"Chuyến đi không phải để mang kinh về. Kinh về tới Trường An, nhưng thứ được truyền đi là một vở diễn: tám mươi mốt nạn, năm ngàn cuộn giấy, một con đường không thể rút ngắn."},"g10":{"t0":544.192,"t1":550.049,"text":"Vì nếu Ngộ Không lộn một vòng là tới, thì chẳng ai tin. Còn mười bốn năm thì ai cũng tin."},"g11":{"t0":550.709,"t1":554.602,"text":"Kịch bản không phải thứ giả. Nó là thứ duy nhất có thật."},"g12":{"t0":555.262,"t1":559.004,"text":"Và khán giả, là chúng ta, những người vẫn đang lật từng trang."},"g13":{"t0":559.664,"t1":565.506,"text":"Cái vòng trên đầu Ngộ Không không phải vũ khí. Là một sợi dây buộc vào cổ một con vật được thuê."},"g14":{"t0":566.166,"t1":572.57,"text":"Khi vở diễn xong, sợi dây biến mất. Nhưng nó đã làm đúng việc của nó: giữ diễn viên trên sân khấu."},"g16":{"t0":574.4,"t1":582.729,"text":"Khán giả đầu tiên là những oan hồn trong giấc mơ của vua Đường. Khán giả thứ hai là triều đình. Khán giả thứ ba là chúng ta."},"g17":{"t0":583.389,"t1":591.516,"text":"Và vì thế, câu trả lời cho câu hỏi ở đầu phim không phải vì không ai bay được. Mà là: một vở diễn cần thời gian để thành sự thật."},"g18":{"t0":592.176,"t1":595.143,"text":"Đó là lý do chúng ta vẫn đọc nó sau bốn trăm năm."}};
export const SUBS = [{"t0":3.18,"t1":6.954,"text":"Một vòng lộn của Tôn Ngộ Không đi được mười vạn tám ngàn dặm."},{"t0":6.964,"t1":9.324,"text":"Tây Thiên cũng cách đúng chừng ấy."},{"t0":9.334,"t1":12.52,"text":"Vậy mà thầy trò Đường Tăng đi mất mười bốn năm."},{"t0":12.53,"t1":17.796,"text":"Không phải vì không có cách. Mà vì chuyến đi này không phải để tới nơi."},{"t0":17.806,"t1":21.164,"text":"Nó là một vở kịch, đã được dàn dựng từ trước."},{"t0":23.344,"t1":28.793,"text":"Trong mười bốn năm ấy, có tám mươi mốt tai nạn được ghi lại, đánh số, và đếm lại."},{"t0":28.803,"t1":34.048,"text":"Và câu hỏi của phim này rất đơn giản: nếu đó là một vở kịch, ai là đạo diễn?"},{"t0":41.798,"t1":45.894,"text":"Chương một. Vở kịch được viết trước khi có diễn viên."},{"t0":45.904,"t1":53.628,"text":"Hồi thứ tám. Phật Tổ Như Lai nói: cõi Tây phương có ba tạng kinh; Đông Thổ cần, phải có người tới lấy."},{"t0":53.638,"t1":56.636,"text":"Quán Thế Âm nhận lệnh đi tìm người thỉnh kinh."},{"t0":56.646,"t1":59.854,"text":"Dọc đường, bà gặp ba kẻ đang chịu tội."},{"t0":59.864,"t1":67.062,"text":"Lời mời của bà đọc lên như một hợp đồng: theo ta hộ tống người thỉnh kinh; xong việc, tội được xóa, chức cũ được trả."},{"t0":67.072,"t1":72.347,"text":"Sa Tăng nhận. Trư Bát Giới nhận. Tôn Ngộ Không nhận."},{"t0":72.357,"t1":78.926,"text":"Bốn người, một con ngựa, một con đường. Nhưng hợp đồng đã ký trước khi con đường bắt đầu."},{"t0":78.936,"t1":82.979,"text":"Và người ta chỉ ký hợp đồng khi đã biết vở diễn kết thúc thế nào."},{"t0":82.989,"t1":90.189,"text":"Người thỉnh kinh không tự nguyện. Ông được chọn trong một đàn chay do vua tổ chức, rồi được trao một bộ cà sa."},{"t0":90.199,"t1":97.585,"text":"Ba người kia cũng không tự nguyện. Họ đang chịu hình phạt. Đây là cơ hội duy nhất để được tha."},{"t0":97.595,"t1":105.897,"text":"Quán Thế Âm đi từ tây sang đông, gặp từng người một. Bà không hỏi họ muốn gì. Bà nói họ sẽ được gì."},{"t0":110.647,"t1":114.094,"text":"Chương hai. Cuốn sổ của đạo diễn."},{"t0":114.104,"t1":120.161,"text":"Quán Thế Âm giữ một cuốn sổ gọi là nạn bạ. Mỗi nạn một dòng, đánh số."},{"t0":120.171,"t1":124.981,"text":"Khi thầy trò về tới Linh Sơn, bà mở sổ, đếm: tám mươi nạn."},{"t0":124.991,"t1":130.782,"text":"Rồi bà nói một câu mà không vở kịch nào dám nói to: còn thiếu một nạn, chưa đủ số."},{"t0":133.362,"t1":136.748,"text":"Bà sai người đuổi theo: làm thêm một nạn nữa."},{"t0":136.758,"t1":142.007,"text":"Không phải tai nạn. Không phải số phận. Một chỉ thị."},{"t0":142.017,"t1":149.008,"text":"Và nạn thứ nhất trong sổ không phải lúc lên đường. Là lúc bị đày xuống trần, trước khi Đường Tăng được sinh ra."},{"t0":149.018,"t1":155.04,"text":"Cuốn sổ bắt đầu trước nhân vật. Nó không ghi lại chuyến đi; nó lên lịch cho chuyến đi."},{"t0":156.22,"t1":166.411,"text":"Tám mươi mốt là con số của Phật giáo: chín lần chín, trở về chân như. Nó không phải số tai nạn xảy ra. Nó là số tai nạn phải xảy ra."},{"t0":166.421,"t1":171.771,"text":"Và người giữ sổ không phải người đi đường. Là người ngồi trên tòa sen."},{"t0":171.781,"t1":179.417,"text":"Nạn bạ không phải nhật ký. Nhật ký ghi cái đã xảy ra. Nạn bạ ghi cái phải xảy ra."},{"t0":179.427,"t1":182.257,"text":"Và người đếm là người đã viết kịch bản."},{"t0":187.207,"t1":191.018,"text":"Chương ba. Yêu quái nào cũng có người quen."},{"t0":191.028,"t1":196.097,"text":"Ở núi Bình Đỉnh, hai con yêu quái bị bắt. Lão Tử xuống đòi."},{"t0":196.107,"t1":200.586,"text":"Ông nói: đó là hai đứa trẻ giữ lò vàng, lò bạc của ta."},{"t0":200.596,"t1":212.173,"text":"Rồi ông nói thêm một câu, và cả vở kịch đứng hình. Chính Bồ Tát Quán Thế Âm đã hỏi mượn ta ba lần, đưa chúng xuống đây, hóa thành yêu quái, để thử xem thầy trò có thật lòng đi Tây Thiên không."},{"t0":215.553,"t1":220.963,"text":"Không phải yêu quái. Là diễn viên quần chúng, do chính người bảo trợ tuyển."},{"t0":220.973,"t1":230.452,"text":"Những lần khác cũng vậy. Sư tử của Văn Thù. Cá vàng trong ao sen của Quán Âm. Con sư tử lông vàng bà cưỡi."},{"t0":230.462,"t1":236.912,"text":"Con nào cũng có chủ. Và chủ luôn tới đúng lúc gậy sắp giáng xuống: khoan, con ta."},{"t0":236.922,"t1":247.681,"text":"Ở núi Sư Đà, ba con yêu quái lớn nhất: sư tử của Văn Thù, voi của Phổ Hiền, và đại bàng, anh em cùng mẹ với chim khổng tước, kẻ mà Phật Tổ từng gọi là cậu của mình."},{"t0":247.691,"t1":255.466,"text":"Đại bàng từ chối lên trời. Nó nói: trên đó ăn chay, nghèo lắm; ở đây ta ăn thịt người, sướng hơn."},{"t0":255.476,"t1":259.374,"text":"Còn ba con tê giác ở núi Thanh Long thì không có ai tới đòi."},{"t0":259.384,"t1":265.706,"text":"Chúng bị giết. Sừng bị cưa. Một chiếc sừng được gửi lên Linh Sơn làm quà."},{"t0":265.716,"t1":272.707,"text":"Câu yêu quái có ô dù thì được đón về, không có thì bị đánh chết, là câu của Internet, không có trong truyện."},{"t0":272.717,"t1":276.898,"text":"Nhưng ba con tê giác thì có thật. Và chúng chết thật."},{"t0":278.078,"t1":286.906,"text":"Không phải vì truyện tàn nhẫn. Vì truyện rất nhất quán: cái gì thuộc về ai thì trả về người đó; cái gì không thuộc về ai thì bị xóa."},{"t0":286.916,"t1":290.577,"text":"Và trong một vở diễn, ai cũng phải thuộc về một người."},{"t0":290.587,"t1":299.992,"text":"Đại bàng đòi ăn thịt cả một nước. Phật Tổ hứa: ai làm việc thiện, ta cho ngươi ăn trước. Một thỏa thuận, không phải một hình phạt."},{"t0":304.942,"t1":308.573,"text":"Chương bốn. Kinh sách là một món hàng."},{"t0":308.583,"t1":315.4,"text":"Đường Tăng tới Linh Sơn. Hai đệ tử của Phật dẫn vào kho, rồi hỏi: có nhân sự không?"},{"t0":315.41,"t1":320.686,"text":"Nhân sự nghĩa là quà. Không có quà, họ đưa kinh không chữ."},{"t0":320.696,"t1":323.286,"text":"Năm ngàn bốn mươi tám cuộn giấy trắng."},{"t0":323.296,"t1":329.806,"text":"Phật Tổ biết. Ngài cười, và phán: kinh không thể truyền không công, cũng không thể lấy không."},{"t0":329.816,"t1":336.091,"text":"Ngài kể chuyện lần trước bán kinh cho một nhà giàu, lấy ba đấu ba thăng vàng, mà còn chê là bán rẻ."},{"t0":336.101,"t1":341.95,"text":"Đường Tăng không có gì. Chỉ có chiếc bình bát bằng vàng, do chính vua Đường ban."},{"t0":341.96,"t1":350.62,"text":"Ông đưa. Vị đệ tử nhận, mỉm cười. Các vị khác trêu: không biết xấu hổ à, đòi quà của người ta."},{"t0":350.63,"t1":353.144,"text":"Nhưng tay thì vẫn giữ chặt chiếc bình."},{"t0":354.324,"t1":359.418,"text":"Đổi lại, họ đưa kinh có chữ: năm ngàn bốn mươi tám cuộn, đúng một tạng."},{"t0":359.428,"t1":362.644,"text":"Và chuyến đi kéo dài năm ngàn bốn mươi tám ngày."},{"t0":362.654,"t1":367.822,"text":"Cùng một con số. Không phải ngẫu nhiên. Là định mức."},{"t0":367.832,"t1":376.182,"text":"Người trả tiền thật không phải nhà sư. Là vua Đường, người dựng đàn chay bốn mươi chín ngày để yên lòng các oan hồn trong giấc mơ của mình."},{"t0":376.192,"t1":380.765,"text":"Ông hỏi: bao giờ về? Nhà sư đáp: ba năm."},{"t0":380.775,"t1":383.044,"text":"Mười bốn năm sau mới về."},{"t0":384.224,"t1":392.886,"text":"Kinh không chữ không phải trò lừa. Nó là món hàng thử: nếu người mua không biết mình mua gì, thì thứ họ nhận được đúng là không có gì."},{"t0":392.896,"t1":398.403,"text":"Nhưng khi đã trả giá, họ nhận được chữ. Và chữ nào cũng có giá."},{"t0":398.413,"t1":403.201,"text":"Nhà văn Minh viết về thiên đình, nhưng cái kho đọc lên thấy giống hệt một công đường."},{"t0":403.211,"t1":408.184,"text":"Món hàng ấy không phải giấy. Là quyền nói rằng trời đã chứng giám."},{"t0":413.934,"t1":417.894,"text":"Chương năm. Thứ duy nhất không có trong kịch bản."},{"t0":417.904,"t1":426.307,"text":"Trên đường về, họ qua sông Thông Thiên. Con rùa già chở họ, rồi hỏi: tôi nhờ hỏi Phật, tôi còn sống được bao lâu?"},{"t0":426.317,"t1":428.167,"text":"Đường Tăng quên."},{"t0":428.177,"t1":430.791,"text":"Rùa lặn. Kinh ướt."},{"t0":430.801,"t1":435.809,"text":"Họ phơi kinh trên đá. Một cuộn bị dính, rách mất phần cuối."},{"t0":435.819,"t1":449.195,"text":"Đường Tăng hối hận. Ngộ Không cười: không phải lỗi ở đây. Trời đất còn không trọn vẹn; kinh này vốn đã trọn, nay bị rách, ấy là ứng với lẽ không trọn vẹn. Sức người nào làm được?"},{"t0":452.175,"t1":457.527,"text":"Đó là câu duy nhất trong cả vở kịch thừa nhận: có một chỗ, kịch bản không với tới."},{"t0":457.537,"t1":462.508,"text":"Và chỗ đó không phải tai nạn. Là một lỗ hổng được giữ lại."},{"t0":463.688,"t1":471.635,"text":"Nhà phê bình Hồ Thích nói: đừng tìm ẩn ý. Truyện này là một trò đùa, một thứ châm biếm lạnh, và giá trị của nó nằm ở đó."},{"t0":471.645,"t1":476.795,"text":"Ông đúng. Nhưng một trò đùa về một vở diễn thì vẫn là một vở diễn."},{"t0":476.805,"t1":482.596,"text":"Nạn thứ tám mươi mốt không do ai lên kế hoạch. Nó do một con rùa già quyết định."},{"t0":482.606,"t1":485.585,"text":"Và đó là nạn duy nhất làm hỏng món hàng."},{"t0":485.595,"t1":491.591,"text":"Đó là lý do câu chuyện phải để nó rách. Một món hàng hoàn hảo thì không cần người đọc."},{"t0":496.741,"t1":499.474,"text":"Chương sáu. Khán giả."},{"t0":499.484,"t1":503.475,"text":"Ở bến Lăng Vân, thầy trò qua sông trên con thuyền không đáy."},{"t0":503.485,"t1":509.438,"text":"Một cái xác trôi ngang. Cả bốn người cùng chỉ tay. Chính là ông."},{"t0":509.448,"t1":514.354,"text":"Người thỉnh kinh cũ đã chết giữa sông. Người qua bờ là người khác."},{"t0":515.934,"t1":522.413,"text":"Lên tới Linh Sơn, họ được phong. Đường Tăng thành Phật. Ngộ Không thành Phật."},{"t0":522.423,"t1":525.487,"text":"Ngộ Không sờ đầu: cái vòng đã biến mất."},{"t0":525.497,"t1":529.349,"text":"Ông xin đập vỡ nó, để không ai bị trò đó chơi nữa."},{"t0":529.359,"t1":532.664,"text":"Và đây là câu trả lời cho câu hỏi ở đầu phim."},{"t0":533.644,"t1":544.132,"text":"Chuyến đi không phải để mang kinh về. Kinh về tới Trường An, nhưng thứ được truyền đi là một vở diễn: tám mươi mốt nạn, năm ngàn cuộn giấy, một con đường không thể rút ngắn."},{"t0":544.142,"t1":550.649,"text":"Vì nếu Ngộ Không lộn một vòng là tới, thì chẳng ai tin. Còn mười bốn năm thì ai cũng tin."},{"t0":550.659,"t1":555.202,"text":"Kịch bản không phải thứ giả. Nó là thứ duy nhất có thật."},{"t0":555.212,"t1":559.604,"text":"Và khán giả, là chúng ta, những người vẫn đang lật từng trang."},{"t0":559.614,"t1":566.106,"text":"Cái vòng trên đầu Ngộ Không không phải vũ khí. Là một sợi dây buộc vào cổ một con vật được thuê."},{"t0":566.116,"t1":573.17,"text":"Khi vở diễn xong, sợi dây biến mất. Nhưng nó đã làm đúng việc của nó: giữ diễn viên trên sân khấu."},{"t0":574.35,"t1":583.329,"text":"Khán giả đầu tiên là những oan hồn trong giấc mơ của vua Đường. Khán giả thứ hai là triều đình. Khán giả thứ ba là chúng ta."},{"t0":583.339,"t1":592.116,"text":"Và vì thế, câu trả lời cho câu hỏi ở đầu phim không phải vì không ai bay được. Mà là: một vở diễn cần thời gian để thành sự thật."},{"t0":592.126,"t1":595.743,"text":"Đó là lý do chúng ta vẫn đọc nó sau bốn trăm năm."}];
